package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonStringFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.BeanSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.JsonSerializer;
import com.fasterxml.jackson.databind.ser.SerializerProvider;
import com.fasterxml.jackson.databind.ser.impl.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.impl.PropertyAccessor;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.LinkedHashSet;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class JsonValueSerializer_acceptJsonFormatVisitor_TriageGen0Test {

    private JsonValueSerializer serializer;
    private JsonFormatVisitorWrapper visitor;
    private JavaType typeHint;
    private SerializerProvider provider;
    private PropertyAccessor accessorMethod;

    // Mocking the internal fields since they are private/protected and no public constructor sets them
    // We use reflection to inject them into the instance for testing purposes
    @Before
    public void setUp() throws Exception {
        serializer = mock(JsonValueSerializer.class, spies(JsonValueSerializer.class));
        visitor = mock(JsonFormatVisitorWrapper.class);
        typeHint = mock(JavaType.class);
        provider = mock(SerializerProvider.class);
        accessorMethod = mock(PropertyAccessor.class);

        when(visitor.getProvider()).thenReturn(provider);

        // Injecting private fields via reflection to simulate the state of a real JsonValueSerializer
        setInternalField(serializer, "_accessorMethod", accessorMethod);
        setInternalField(serializer, "_property", null);
    }

    private void setInternalField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    /**
     * Test case: Declaring class is an Enum and _acceptJsonFormatVisitorForEnum returns true.
     * Covers the first branch: (declaring != null) && declaring.isEnum() AND returning early.
     */
    @Test
    public void testAcceptJsonFormatVisitor_EnumSpecialHandlingTrue() throws Exception {
        enum TestEnum { INSTANCE }
        Class<?> enumClass = TestEnum.class;
        JavaType type = mock(JavaType.class);

        when(accessorMethod.getDeclaringClass()).thenReturn(enumClass);
        when(accessorMethod.getType()).thenReturn(type);

        // Spy the serializer to mock the protected method
        JsonValueSerializer spySerializer = spy(serializer);
        setInternalField(spySerializer, "_accessorMethod", accessorMethod);

        doReturn(true).when(spySerializer)._acceptJsonFormatVisitorForEnum(eq(visitor), eq(typeHint), eq(enumClass));

        spySerializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(spySerializer)._acceptJsonFormatVisitorForEnum(visitor, typeHint, enumClass);
        verify(spySerializer, never()).acceptJsonFormatVisitor(any(), any()); // Should return early
    }

    /**
     * Test case: Declaring class is an Enum but _acceptJsonFormatVisitorForEnum returns false.
     * Covers the branch where enum check passes but falls through to serializer logic.
     */
    @Test
    public void testAcceptJsonFormatVisitor_EnumSpecialHandlingFalse() throws Exception {
        enum TestEnum { INSTANCE }
        Class<?> enumClass = TestEnum.class;
        JavaType type = mock(JavaType.class);
        JsonSerializer<Object> mockSer = mock(JsonSerializer.class);

        when(accessorMethod.getDeclaringClass()).thenReturn(enumClass);
        when(accessorMethod.getType()).thenReturn(type);
        setInternalField(serializer, "_valueSerializer", mockSer);

        JsonValueSerializer spySerializer = spy(serializer);
        setInternalField(spySerializer, "_accessorMethod", accessorMethod);
        setInternalField(spySerializer, "_valueSerializer", mockSer);

        doReturn(false).when(spySerializer)._acceptJsonFormatVisitorForEnum(eq(visitor), eq(typeHint), eq(enumClass));

        spySerializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(spySerializer)._acceptJsonFormatVisitorForEnum(visitor, typeHint, enumClass);
        verify(mockSer).acceptJsonFormatVisitor(visitor, null);
    }

    /**
     * Test case: Declaring class is NOT an Enum, and _valueSerializer is NOT null.
     * Covers the standard path.
     */
    @Test
    public void testAcceptJsonFormatVisitor_NotEnumWithSerializer() throws Exception {
        JavaType type = mock(JavaType.class);
        JsonSerializer<Object> mockSer = mock(JsonSerializer.class);

        when(accessorMethod.getDeclaringClass()).thenReturn(String.class);
        when(accessorMethod.getType()).thenReturn(type);
        setInternalField(serializer, "_valueSerializer", mockSer);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(mockSer).acceptJsonFormatVisitor(visitor, null);
    }

    /**
     * Test case: Declaring class is NOT an Enum, _valueSerializer is null, and provider finds serializer.
     * Covers the branch where ser is null and then retrieved from provider.
     */
    @Test
    public void testAcceptJsonFormatVisitor_SerializerFromProvider() throws Exception {
        JavaType type = mock(JavaType.class);
        JsonSerializer<Object> mockSer = mock(JsonSerializer.class);

        when(accessorMethod.getDeclaringClass()).thenReturn(String.class);
        when(accessorMethod.getType()).thenReturn(type);
        setInternalField(serializer, "_valueSerializer", null);
        when(provider.findTypedValueSerializer(type, false, null)).thenReturn(mockSer);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(provider).findTypedValueSerializer(type, false, null);
        verify(mockSer).acceptJsonFormatVisitor(visitor, null);
    }

    /**
     * Test case: Declaring class is NOT an Enum, _valueSerializer is null, and provider returns null.
     * Covers the branch where visitor.expectAnyFormat(typeHint) is called.
     */
    @Test
    public void testAcceptJsonFormatVisitor_SerializerNotFound() throws Exception {
        JavaType type = mock(JavaType.class);

        when(accessorMethod.getDeclaringClass()).thenReturn(String.class);
        when(accessorMethod.getType()).thenReturn(type);
        setInternalField(serializer, "_valueSerializer", null);
        when(provider.findTypedValueSerializer(type, false, null)).thenReturn(null);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(visitor).expectAnyFormat(typeHint);
    }

    /**
     * Test case: Declaring class is null.
     * Covers the (declaring != null) branch being false.
     */
    @Test
    public void testAcceptJsonFormatVisitor_DeclaringNull() throws Exception {
        JavaType type = mock(JavaType.class);
        JsonSerializer<Object> mockSer = mock(JsonSerializer.class);

        when(accessorMethod.getDeclaringClass()).thenReturn(null);
        when(accessorMethod.getType()).thenReturn(type);
        setInternalField(serializer, "_valueSerializer", mockSer);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(mockSer).acceptJsonFormatVisitor(visitor, null);
    }
}
